-- NOTE: 1 source name(s) collapse into an existing sibling slug.
-- The first name wins; the duplicate name is not stored as a separate row:
--   equatorial-guinea/wele-nzas-province/aconibe-and-anisok-area/anisok  <-- keeps "Añisok", drops duplicate "Anisok"
-- ============================================================================

-- 0. Country row (adds any territory missing from the base schema seed)
insert into public.countries (code, name) values
  ('GQ', 'Equatorial Guinea')
on conflict (code) do update set name = excluded.name;

-- 1. Country root (level 1)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'GQ', null, 'Equatorial Guinea', 'Country', 1, 'equatorial-guinea', 0
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level;

-- 2. Level 2 (8 rows)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'GQ', p.id, v.name, v.location_type, v.level, v.path, v.sort_order
from (values
    ('equatorial-guinea', 'Annobón Province', 'Province', 2, 'equatorial-guinea/annobon-province', 0),
    ('equatorial-guinea', 'Bioko Norte Province', 'Province', 2, 'equatorial-guinea/bioko-norte-province', 1),
